        "confidence": {
          "type": "integer",
          "minimum": 0,
          "maximum": 100
        },
        "scene_key": {
          "type": "string",
          "minLength": 1,
          "maxLength": 160
        },
        "evidence_refs": {
          "$ref": "#/$defs/evidenceRefs"
        },
